/**
 * Shared basemap registry (one source of truth for all three map components).
 *
 * Every source below is free and needs NO API key. CARTO Positron was retired
 * behind a key, so the dashboard offers the keyless alternatives instead.
 *
 * Note the ArcGIS REST endpoints address tiles as `{z}/{y}/{x}` (row-first),
 * unlike OSM-style `{z}/{x}/{y}`; Leaflet substitutes whatever placeholders
 * the URL contains, so each source just spells its own order.
 */

export interface Basemap {
  id: string;
  label: string;
  url: string;
  attribution: string;
  /** OSM-style subdomains (a/b/c) when the host exposes them. */
  subdomains?: string;
}

