export const BASEMAP_BY_ID: Map<string, Basemap> = new Map(
  BASEMAPS.map((b) => [b.id, b])
);

const STORAGE_KEY = 'miway_basemap';

export function defaultBasemapId(): string {
  try {
    return localStorage.getItem(STORAGE_KEY) || 'osm_hot';
  } catch {
    return 'osm_hot';
  }
}

export function saveBasemapId(id: string): void {
  try {
    localStorage.setItem(STORAGE_KEY, id);
  } catch {
    // private mode / storage disabled — non-fatal
  }
}

export function basemapById(id: string | null | undefined): Basemap {
  return (id && BASEMAP_BY_ID.get(id)) || BASEMAPS[0];
}

/** Broadcast that the active basemap changed (pickers tell the maps). */
export function notifyBasemapChanged(id: string): void {
  window.dispatchEvent(new CustomEvent('miway:basemap', { detail: id }));
}